function User(name, age) {
  this.name = name
  this.age = age
}
const ValidatedUser = new Proxy(User, {
  construct(target, args) {
    if (args[1] < 0) throw new Error("Age cannot be negative")
    return new target(...args)
  }
})
const user1 = new ValidatedUser("Hariom", 25)
try {
  const user2 = new ValidatedUser("Amit", -5)
} catch(e) {
  return { user1: user1.name, error: e.message }
}
